<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;use Illuminate\Database\Eloquent\SoftDeletes;
class GuiaInterna extends Model{use SoftDeletes;protected $table='guias_internas';protected $fillable=['sincronizacion_id','restaurant_id','serie','correlativo','local_origen_id','local_origen','local_destino_id','local_destino','direccion_destino','direccion_destino_payload','almacen_id','almacen','fecha_registro','fecha_emision','fecha_traslado','motivo_id','motivo','estado_codigo','estado','recepcionada','pendiente_procesar_stock','total','total_items','requerimiento_restaurant_id','movimiento_restaurant_id','observacion','payload_restaurant','sincronizado_en'];protected function casts():array{return['fecha_registro'=>'datetime','fecha_emision'=>'datetime','fecha_traslado'=>'datetime','total'=>'decimal:4','direccion_destino_payload'=>'array','payload_restaurant'=>'array','sincronizado_en'=>'datetime'];}public function detalles():HasMany{return $this->hasMany(GuiaInternaDetalle::class);}public function sincronizacion():BelongsTo{return $this->belongsTo(GuiaInternaSincronizacion::class,'sincronizacion_id');}}
